B.Oc=new A.aF("gecici_03",B.c5,"\u0130htiyati tedbir ile ihtiyati haciz aras\u0131ndaki temel fark a\u015fa\u011f\u0131dakilerden hangisidir?",B.Hu,1,"Temel ayr\u0131m konular\u0131ndad\u0131r: \u0130htiyati tedbir para d\u0131\u015f\u0131ndaki \xe7eki\u015fmeli \u015fey/hakk\u0131n korunmas\u0131na (HMK m. 389 vd.), ihtiyati haciz ise para alaca\u011f\u0131n\u0131n g\xfcvenceye al\u0131nmas\u0131na (\u0130\u0130K m. 257 vd.) hizmet eder.")
B.I9=s(["Hakl\u0131l\u0131\u011f\u0131n\u0131 tam (kesin) olarak ispatlamal\u0131d\u0131r.","Hakl\u0131l\u0131\u011f\u0131n\u0131 yakla\u015f\u0131k olarak ispat etmelidir.","Hi\xe7bir ispat y\xfck\xfc yoktur.","Yaln\u0131zca yemin etmesi yeterlidir."],t.s)
