B.O7=new A.aF("taraf_01",B.c6,"Feragat nedir?",B.Jg,1,"HMK m. 307: Feragat, davac\u0131n\u0131n talep sonucundan k\u0131smen veya tamamen vazge\xe7mesidir.")
B.Ia=s(["Davac\u0131n\u0131n davas\u0131ndan vazge\xe7mesidir.","Daval\u0131n\u0131n, davac\u0131n\u0131n talep sonucuna k\u0131smen veya tamamen muvafakat etmesidir.","Taraflar\u0131n uzla\u015fmas\u0131d\u0131r.","Mahkemenin davay\u0131 kabul etmesidir."],t.s)
B.O8=new A.aF("taraf_02",B.c6,"Kabul nedir?",B.Ia,1,"HMK m. 308: Kabul, davac\u0131n\u0131n talep sonucuna daval\u0131n\u0131n k\u0131smen veya tamamen muvafakat etmesidir.")
